from pathlib import Path
import json,csv,math,hashlib
P=Path(__file__).resolve().parent
S=json.loads((P/'summary.json').read_text());cells={}
for p in (P/'cells').glob('*_m*.json'):
 x=json.loads(p.read_text());cells[x['world'],x['m']]=x
coverage=[]
for w in ['zeta','dh','plant']:
 for m in range(16,121):
  x=cells.get((w,m));coverage.append(dict(world=w,m=m,status='COMPUTED' if x else 'NOT_YET_COMPUTED',source_matrix_available=(P/'matrices'/f'cell_{w}_m{m}.npz').exists(),checkpoint_sha256=hashlib.sha256((P/'cells'/f'{w}_m{m}.json').read_bytes()).hexdigest() if x else None))
